def solve(inp):
    h,w=len(inp),len(inp[0])
    lrows=[i for i in range(h) if all(v==8 for v in inp[i])]
    lcols=[j for j in range(w) if all(inp[i][j]==8 for i in range(h))]
    def rid(i, lines):
        r=0
        for L in lines:
            if i>L: r+=1
        return r
    rlines=[i for i in range(h) if i not in lrows]  # not helpful
    # build region id per row: count separators before
    def rowreg(i): return sum(1 for L in lrows if L<i)
    def colreg(j): return sum(1 for L in lcols if L<j)
    nR=rowreg(h-1)+1 if lrows else 1
    nC=colreg(w-1)+1 if lcols else 1
    cells={}
    for i in range(h):
        for j in range(w):
            v=inp[i][j]
            if v not in (0,8):
                cells.setdefault(v,[]).append((rowreg(i),colreg(j)))
    paint=[[set() for _ in range(nC)] for _ in range(nR)]
    for c,ps in cells.items():
        for a in range(len(ps)):
            for b in range(a+1,len(ps)):
                (r1,c1),(r2,c2)=ps[a],ps[b]
                if r1==r2:
                    for cc in range(min(c1,c2),max(c1,c2)+1): paint[r1][cc].add(c)
                if c1==c2:
                    for rr in range(min(r1,r2),max(r1,r2)+1): paint[rr][c1].add(c)
    # singletons: fill entire row region (observed in demo1)
    for c,ps in cells.items():
        if len(ps)==1:
            r,cc=ps[0]
            for j in range(nC): paint[r][j].add(c)
    out=[row[:] for row in inp]
    for i in range(h):
        if i in lrows: continue
        for j in range(w):
            if j in lcols: continue
            s=paint[rowreg(i)][colreg(j)]
            if len(s)==1: out[i][j]=next(iter(s))
            elif len(s)>1: out[i][j]=sum(s)+1
    return out

